<script setup lang="ts">
import { computed, ref } from 'vue'
import { z } from 'zod'
import { message, type ApiClient } from '../../api'
import { duration } from '../../duration'
import { money, packageSchema, packagesSchema, type TimePackage } from '../../payments'
import { useResource } from '../../composables/useResource'
import PageHeader from '../../components/ui/PageHeader.vue'
import Button from '../../components/ui/Button.vue'
import Panel from '../../components/ui/Panel.vue'
import DataTable from '../../components/ui/DataTable.vue'
import StatusTag from '../../components/ui/StatusTag.vue'
import EmptyState from '../../components/ui/EmptyState.vue'
import Metric from '../../components/ui/Metric.vue'
import PackageEditor from '../../components/business-rewick/PackageEditor.vue'
import ActionConfirm from '../../components/business-rewick/ActionConfirm.vue'
const props = defineProps<{ api: ApiClient; active?: boolean }>()
const { state, reload } = useResource(props.api, '/admin/packages', packagesSchema)
const updated = ref<TimePackage[]>([]), archived = ref<number[]>([]), editing = ref<TimePackage | null>(null), selectedId = ref<number | null>(null), adding = ref(false), toggling = ref<TimePackage | null>(null), removing = ref<TimePackage | null>(null), busy = ref(false), error = ref(''), notice = ref('')
const items = computed(() => state.value.kind === 'ready' ? [...state.value.data.filter(item => !updated.value.some(value => value.id === item.id)), ...updated.value].filter(item => !archived.value.includes(item.id)).sort((a,b) => a.sortOrder - b.sortOrder || a.id - b.id) : [])
const selected = computed(() => items.value.find(item => item.id === selectedId.value) ?? items.value[0])
const columns = [{ key: 'sortOrder', title: '排序' }, { key: 'name', title: '套餐名称' }, { key: 'price', title: '售价' }, { key: 'duration', title: '面试时长' }, { key: 'enabled', title: '状态' }, { key: 'actions', title: '操作', className: 'col-actions' }]
function saved(item: TimePackage) { updated.value = [...updated.value.filter(value => value.id !== item.id), item]; adding.value = false; editing.value = null; selectedId.value = item.id; notice.value = '套餐已保存。启用的套餐将展示在桌面端。' }
async function archive() { if (!removing.value || busy.value) return; const id = removing.value.id; busy.value = true; error.value = ''; try { await props.api.request(`/admin/packages/${id}`, z.undefined(), { method: 'DELETE' }); archived.value.push(id); removing.value = null; editing.value = null; notice.value = '套餐已归档，原有订单不受影响。' } catch (failure) { error.value = message(failure) } finally { busy.value = false } }
async function toggle() { if (!toggling.value || busy.value) return; const { id, priceCents: _price, ...draft } = toggling.value; busy.value = true; error.value = ''; try { const result = await props.api.request(`/admin/packages/${id}`, packageSchema, { method: 'PUT', body: { ...draft, enabled: !draft.enabled } }); saved(result); toggling.value = null } catch (failure) { error.value = message(failure) } finally { busy.value = false } }
function packageDuration(seconds: number) { return seconds % 3600 === 0 ? `${seconds / 3600} 小时` : duration(seconds) }
</script>
<template><div class="page"><PageHeader title="套餐管理" desc="管理在售套餐与面试时长"><Button variant="primary" icon="plus" @click="adding = true">添加套餐</Button></PageHeader><div class="stack"><p v-if="notice" role="status" class="business-notice business-feedback">{{ notice }}</p><p v-if="state.kind === 'loading'" role="status">正在加载…</p><p v-else-if="state.kind === 'error'" class="field-error" role="alert">{{ state.error }}<Button @click="reload">重试</Button></p><EmptyState v-else-if="!items.length" title="尚无套餐，请添加。" /><template v-else><div class="package-grid"><article v-for="item in items" :key="item.id" class="panel m-surface bento package-card" :aria-label="item.name"><header class="panel-head"><Button variant="text" :aria-pressed="selected?.id === item.id" @click="selectedId = item.id">{{ item.name }}</Button><StatusTag :status="item.enabled" on="已上架" off="已下架" /></header><div class="package-body"><Metric :value="item.priceCents / 100" :decimals="2" unit="元" /><del v-if="item.priceCents !== item.originalPriceCents" class="muted">{{ money(item.originalPriceCents) }}</del><p>面试时长 · {{ packageDuration(item.durationSeconds) }}</p><p class="muted">{{ item.description || '暂无套餐说明' }}</p><p class="muted">排序 {{ item.sortOrder }} · 长期有效</p><div class="row-actions"><Button :aria-label="`编辑套餐 ${item.name}`" @click="editing = item">编辑套餐</Button><Button :aria-label="`${item.enabled ? '下架' : '上架'} ${item.name}`" @click="error = ''; toggling = item">{{ item.enabled ? '下架' : '上架' }}</Button></div></div></article></div><Panel class="reveal" title="套餐展示顺序" :meta="`共 ${items.length} 个套餐`"><DataTable :columns="columns" :data="items"><template #cell-price="{ row }">{{ money(row.priceCents) }}</template><template #cell-duration="{ row }">{{ packageDuration(row.durationSeconds) }}</template><template #cell-enabled="{ row }"><StatusTag :status="row.enabled" on="已上架" off="已下架" /></template><template #cell-actions="{ row }"><Button variant="text" size="sm" :aria-label="`修改排序 ${row.name}`" @click="editing = row">编辑</Button></template></DataTable></Panel><Panel v-if="selected" class="reveal" title="套餐信息"><template #tools><Button variant="text" @click="editing = selected">修改资料</Button></template><dl class="kv-grid"><div class="kv"><dt class="kv-label">当前查看</dt><dd class="kv-value">{{ selected.name }}</dd></div><div class="kv"><dt class="kv-label">原价</dt><dd class="kv-value">{{ money(selected.originalPriceCents) }}</dd></div><div class="kv"><dt class="kv-label">折扣</dt><dd class="kv-value">{{ selected.discountBps / 1000 }} 折</dd></div><div class="kv"><dt class="kv-label">时效</dt><dd class="kv-value">长期有效</dd></div><div class="kv"><dt class="kv-label">套餐说明</dt><dd class="kv-value">{{ selected.description || '暂无套餐说明' }}</dd></div></dl></Panel></template><PackageEditor v-if="adding || editing" :key="editing?.id ?? 'new'" :api="api" :item="editing ?? undefined" @close="adding = false; editing = null" @saved="saved" @archive="error = ''; removing = $event" /><ActionConfirm v-if="toggling" :title="toggling.enabled ? '下架套餐' : '上架套餐'" :action="toggling.enabled ? '确认下架' : '确认上架'" :busy="busy" :error="error" @close="toggling = null" @confirm="toggle"><p>{{ toggling.enabled ? `下架「${toggling.name}」后，用户将无法购买此套餐，已有订单不受影响。` : `上架「${toggling.name}」后，将以 ${money(toggling.priceCents)} 在桌面端出售。` }}</p></ActionConfirm><ActionConfirm v-if="removing" title="归档套餐" action="确认归档" :busy="busy" :error="error" @close="removing = null" @confirm="archive"><p>归档「{{ removing.name }}」后不能再创建新订单；已经创建的订单继续按原套餐内容处理。</p></ActionConfirm></div></div></template>
<style scoped>.package-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin-bottom: 20px; }.package-body { display: grid; gap: 14px; padding: 20px; }.package-card { min-width: 0; }.page > .panel { margin-bottom: 16px; }@media(max-width:1100px){.package-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }}@media(max-width:700px){.package-grid{grid-template-columns:minmax(0,1fr);}}</style>
